// Determine path from TXT, if available.
const txtRecords = await DNS.txt(host);
const pathres = txtRecords
  .map(result => result.strings.find(s => s.startsWith("path=")))
  .filter(Boolean);
// Get the string after `path=`.
const path = pathres[0]?.substring(5);

let calendars;
if (path) {
  // If the server has SRV and TXT entries, we already have a full context path to test.
  const uri = `http${secure}://${dnsres[0].host}:${dnsres[0].port}${path}`;
  lazy.log.debug(`[CalDavProvider] Trying ${uri} from SRV and TXT response`);
  calendars = await this.detectCollection(Services.io.newURI(uri));

add_task(async function testDNS() {
  var _srv = DNS.srv;
  var _txt = DNS.txt;
  DNS.srv = function (name) {
    Assert.equal(name, "_caldavs._tcp.dnstest.invalid");
    return [{ prio: 0, weight: 0, host: "example.org", port: 443 }];
  };
  DNS.txt = function (name) {
    Assert.equal(name, "_caldavs._tcp.dnstest.invalid");
    return [{ strings: ["path=/browser/comm/calendar/test/browser/data/dns.sjs"] }];

/**
 * Test that we correctly use DNS discovery. This uses the mochitest server
 * (files in the data directory) instead of CardDAVServer, which has an unusual
 * path, so we can be sure the TXT entry worked.
 */
add_task(async function testDNSWithTXT() {
  const _srv = DNS.srv;
  const _txt = DNS.txt;

  DNS.srv = function (name) {
    Assert.equal(name, "_carddavs._tcp.dnstest.invalid");
    return [{ prio: 0, weight: 0, host: "example.org", port: 443 }];
  };
  DNS.txt = function (name) {
    Assert.equal(name, "_carddavs._tcp.dnstest.invalid");
    return [
      {
        strings: [
          "path=/browser/comm/mail/components/addrbook/test/browser/data/dns.sjs",
        ],
      },
    ];
